import{z as l,x as p,o,c as d,q as t,j as n,D as e,d as r,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"常量传播与折叠","description":"","frontmatter":{"title":"常量传播与折叠","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/constant-propagation.md","filePath":"cs/constant-propagation.md","lastUpdated":1791413859000}'),A={name:"cs/constant-propagation.md"};function c(B,a,h,m,_,f){const E=p("Mermaid");return o(),d("div",null,[a[2]||(a[2]=t('<h1 id="常量传播与折叠" tabindex="-1">常量传播与折叠 <a class="header-anchor" href="#常量传播与折叠" aria-label="Permalink to &quot;常量传播与折叠&quot;">​</a></h1><div class="epigraph"><p>若到达此处的定值都是同一常量，则用该常量替换；折叠把纯运算在编译期算完。二者改 IR，不改语言的操作语义约定。</p><footer>—— 据龙书常量传播；Wegman and Zadeck 前的简单迭代；Appel, Modern Compiler Implementation 整理</footer></div><p>上一课<a href="/cs/null-option">空与 Option</a>把类型单元收到显式测试。中端第一课：主干已有<a href="/cs/reaching-def">到达定义</a>、<a href="/cs/ssa-form">SSA</a>。缺口是<strong>用已知常量改写</strong>：传播把名换成数，折叠把 <code>2+3</code> 变成 <code>5</code>。本课钉简单迭代与 SSA 上的替换；条件分支上的「半格」留给下一课 SCCP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>到达定值给出「哪些写能到这里」。若全部写是 <code>x=3</code>，则读 \\(x\\) 可改成 <code>3</code>。折叠：运算符无副作用则编译期求值。缺口是<strong>替换的合法性</strong>，不是再定义 CFG。</p><p>必须保持<a href="/cs/operational-semantics">操作语义</a>：浮点折叠受 IEEE 与后课 fast-math 约束；除零不能随便折。Option 的 <code>Some 3</code> 可折匹配，<code>None</code> 枝可变成死代码——后课 ADCE。</p><h3 id="折叠不是预处理器" tabindex="-1">折叠不是预处理器 <a class="header-anchor" href="#折叠不是预处理器" aria-label="Permalink to &quot;折叠不是预处理器&quot;">​</a></h3><p>cpp 的常量是记号层；此处是 IR 层，经过类型与地址计算。不要用 <code>#define N 4</code> 当本课定义。</p><p><span class="marginnote">龙书 9.4。Appel 在 SSA 上把传播写成替换。Kildall 的数据流格是背景。本课简单格：⊤/常量/⊤冲突为全⊤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>非 SSA：迭代数据流，格元素为「非常量 / 某常量 / 未定义」。SSA：φ 的操作数全同则 φ 成常量；否则该名非常量。折叠在替换后立即做，可能露出新常量。</p><p><span class="marginnote">φ（phi）节点是 SSA 给「两条路径汇合」起的记号：变量 x 在两个分支里各有版本 x1、x2，汇合处写成 x3 = φ(x1, x2)，走哪条路就取哪个值。两条路给的值相同（都是 3），x3 就能当常量 3 用；一边 3 一边 5，只能标成「非常量」放弃。</span></p>',12)),(o(),n(i,null,{default:e(()=>[s(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22IR%22%5D%20--%3E%20PROP%5B%22%E4%BC%A0%E6%92%AD%E5%B8%B8%E9%87%8F%22%5D%0A%20%20PROP%20--%3E%20FOLD%5B%22%E6%8A%98%E5%8F%A0%E7%BA%AF%E8%BF%90%E7%AE%97%22%5D%0A%20%20FOLD%20--%3E%20IR%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>与<a href="/cs/abstract-interpretation">抽象解释</a>：平坦常量域是 AI 特例，加宽在此不必，因高度为 2。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>副作用：<code>++</code>、调用、volatile 不折。别名：存内存的「常量」要等别名分析——后课。本课先标量 SSA 名。</p><p>不要折 <code>x/x</code> 为 1 当 \\(x\\) 可能为 0，除非语言 UB 允许——<a href="/cs/undefined-behavior-opt">UB 与优化</a> 再收。</p>',4)),(o(),n(i,null,{default:e(()=>[s(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E5%BE%85%E5%8C%96%E7%AE%80%E7%9A%84%E8%BF%90%E7%AE%97%22%5D%20--%3E%20P%7B%22%E6%98%AF%E5%90%A6%E7%BA%AF%E8%BF%90%E7%AE%97%3F%22%7D%0A%20%20P%20--%20%22%E8%87%AA%E5%A2%9E%20%2F%20%E8%B0%83%E7%94%A8%20%2F%20volatile%22%20--%3E%20NO%5B%22%E4%B8%8D%E6%8A%98%E5%8F%A0%2C%20%E4%BF%9D%E6%8C%81%E5%8E%9F%E6%A0%B7%22%5D%0A%20%20P%20--%20%22%E7%BA%AF%E8%BF%90%E7%AE%97%22%20--%3E%20F%7B%22%E6%93%8D%E4%BD%9C%E6%95%B0%E5%85%A8%E6%98%AF%E5%B8%B8%E9%87%8F%3F%22%7D%0A%20%20F%20--%20%22%E6%98%AF%2C%20%E5%A6%82%202%2B3%22%20--%3E%20Y%5B%22%E7%BC%96%E8%AF%91%E6%9C%9F%E7%AE%97%E6%88%90%205%22%5D%0A%20%20F%20--%20%22%E5%90%A6%2C%20%E5%A6%82%20x%2Fx%22%20--%3E%20KEEP%5B%22%E4%B8%8D%E6%9B%BF%E6%8D%A2%2C%20%E7%95%99%E5%88%B0%E8%BF%90%E8%A1%8C%E6%9C%9F%22%5D%0A%20%20F%20--%20%22%E6%B5%AE%E7%82%B9%E8%BF%90%E7%AE%97%22%20--%3E%20IEEE%5B%22%E6%8C%89%20IEEE%20%E8%A7%84%E5%88%99%E8%B0%A8%E6%85%8E%E6%B1%82%E5%80%BC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">数字实例：x = 4 时 x/x 确实等于 1，可 x = 0 时原式是除零错误，而 1 什么错也不报。折叠前编译器得先证明 x 不可能是 0，这往往比证明「x 是常量」还难，所以宁可不折——这就是「保持操作语义」的具体含义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写稀疏条件传播。后课默认：标量常量可在 SSA 上替换。下一课 SCCP：把分支条件也推进格。</p><p>也不把常量传播当过程间内联的替代。</p><p><span class="marginnote">为什么重要：传播本身不删代码，它是删除的前置条件。分支条件一旦变成已知常量，条件为假的整段代码就成了死代码，后一趟删除会把它清掉；没有传播，删除趟往往无事可做。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>传播：到达处唯一常量则替换；折叠：纯运算编译期求值。</li><li>SSA 上是替换；格冲突则放弃。</li><li>副作用与浮点规则限制折叠。</li><li>出处：Aho et al. 龙书；Appel；对照 Cousot 平坦域。</li></ul>',7))])}const x=l(A,[["render",c]]);export{S as __pageData,x as default};
